MATCH (a:Article)
WHERE toLower(coalesce(a.name, '')) CONTAINS 'new ultrathin materials can pull climate-warming co2 from the air'
   OR (
     EXISTS {
       MATCH (a)-[:MENTIONS]->(person:Person)
