Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p)
WHERE (toLower(p.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
OPTIONAL MATCH (a)-[:MENTIONS]->(e:__Entity__)
WITH a, p, collect(DISTINCT e) AS entities
WHERE (
  ((toLower(a.name) CONTAINS 'gpt-4' OR any(e IN entities WHERE toLower(e.name) CONTAINS 'gpt-4' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'gpt-4')))
   AND any(e IN entities WHERE toLower(e.name) CONTAINS 'microsoft' OR toLower(e.name) CONTAINS 'toxicity' OR toLower(e.name) CONTAINS 'susceptibility' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'microsoft' OR toLower(alias) CONTAINS 'toxicity' OR toLower(alias) CONTAINS 'susceptibility')))
  OR
  (any(e IN entities WHERE toLower(e.name) CONTAINS 'elon musk' OR toLower(e.name) CONTAINS 'european commission' OR toLower(e.name) CONTAINS 'disinformation' OR toLower(e.name) CONTAINS 'illegal content' OR toLower(e.name) = 'x' OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'elon musk' OR toLower(alias) CONTAINS 'european commission' OR toLower(alias) CONTAINS 'disinformation' OR toLower(alias) CONTAINS 'illegal content' OR toLower(alias) = 'x')))
)
RETURN a.name AS article, a.published_on AS published_on, p.name AS publisher, [e IN entities WHERE e.name IS NOT NULL | e.name] AS connected_entities
