Cypher query: MATCH (a:Article)-[r:PUBLISHED_BY]->(p)
WHERE (
  'Publisher' IN labels(p) OR 'Organization' IN labels(p)
)
AND (
  (
    (toLower(p.name) CONTAINS 'the roar' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the roar'))
    AND (
      toLower(a.name) CONTAINS 'tasmania jackjumpers'
      OR toLower(a.name) CONTAINS 'sydney kings'
      OR EXISTS {
        MATCH (a)-[:MENTIONS]->(e)
        WHERE toLower(e.name) CONTAINS 'tasmania jackjumpers'
           OR toLower(e.name) CONTAINS 'sydney kings'
           OR toLower(e.name) CONTAINS 'jaylin galloway'
           OR toLower(e.name) CONTAINS 'jonah bolden'
           OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'tasmania jackjumpers' OR toLower(alias) CONTAINS 'sydney kings' OR toLower(alias) CONTAINS 'jaylin galloway' OR toLower(alias) CONTAINS 'jonah bolden')
      }
    )
  )
  OR
  (
    (toLower(p.name) CONTAINS 'sporting news' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sporting news'))
    AND (
      toLower(a.name) CONTAINS 'texas rangers'
      OR EXISTS {
        MATCH (a)-[:MENTIONS]->(e)
        WHERE toLower(e.name) CONTAINS 'texas rangers'
           OR any(alias IN coalesce(e.aliases, []) WHERE toLower(alias) CONTAINS 'texas rangers')
      }
    )
  )
)
RETURN DISTINCT a.name AS title, p.name AS publisher, type(r) AS publisher_connection
LIMIT 10
