Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher),
      (a)-[:MENTIONS]->(g:Organization),
      (a)-[:MENTIONS]->(t:__Entity__)
WHERE (
  toLower(p.name) CONTAINS 'the verge'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the verge')
  OR toLower(p.name) CONTAINS 'techcrunch'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch')
)
AND (
  toLower(g.name) CONTAINS 'google'
  OR any(alias IN coalesce(g.aliases, []) WHERE toLower(alias) CONTAINS 'google')
)
AND (
  (
    (toLower(p.name) CONTAINS 'the verge' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the verge'))
    AND any(term IN ['android', 'app distribution', 'in-app payment', 'in app payment'] WHERE
      toLower(t.name) CONTAINS term OR any(alias IN coalesce(t.aliases, []) WHERE toLower(alias) CONTAINS term))
  )
  OR
  (
    (toLower(p.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
    AND any(term IN ['android', 'app distribution', 'in-app payment', 'in app payment', 'news content', 'news distribution'] WHERE
      toLower(t.name) CONTAINS term OR any(alias IN coalesce(t.aliases, []) WHERE toLower(alias) CONTAINS term))
  )
)
RETURN DISTINCT a.name AS article, a.published_on AS published_on, p.name AS publisher, 'PUBLISHED_BY' AS publisher_relationship, g.name AS google, 'MENTIONS' AS google_relationship, t.name AS related_topic
LIMIT 10
