Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p)
MATCH (a)-[:MENTIONS]->(m:Organization), (a)-[:MENTIONS]->(b:Organization)
WHERE (
  toLower(p.name) CONTAINS 'the guardian'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'the guardian')
  OR toLower(p.name) CONTAINS 'sporting news'
  OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sporting news')
)
AND (
  toLower(m.name) CONTAINS 'manchester united'
  OR any(alias IN coalesce(m.aliases, []) WHERE toLower(alias) CONTAINS 'manchester united')
)
AND (
  toLower(b.name) CONTAINS 'bayern munich'
  OR any(alias IN coalesce(b.aliases, []) WHERE toLower(alias) CONTAINS 'bayern munich')
)
OPTIONAL MATCH (a)-[r:MENTIONS|PARTICIPATED_IN|SAID|PART_OF]->(e:__Entity__)
WITH a, p, collect(DISTINCT {name: e.name, relationship: type(r)}) AS connected_entities
RETURN a.name AS article_title, p.name AS publisher, a.published_on AS date, connected_entities
LIMIT 10
